const int LED = {{led_pin}};
const unsigned long P = {{period_ms}};
unsigned long last = 0;
bool state = false;

void setup() {
  pinMode(LED, OUTPUT);
}

void loop() {
  unsigned long now = millis();
  if (now - last >= P) {
    last = now;
    state = !state;
    digitalWrite(LED, state);
  }
}
